<?php
class Budget extends Model
{
 protected $table='budgets';
 public function references(){return['years'=>$this->query("SELECT * FROM budget_fiscal_years WHERE status='open' AND deleted_at IS NULL ORDER BY start_date DESC")->fetchAll(),'periods'=>$this->query("SELECT p.*,y.code year_code FROM budget_periods p JOIN budget_fiscal_years y ON y.id=p.fiscal_year_id WHERE p.status='open' ORDER BY p.start_date")->fetchAll(),'sites'=>$this->query("SELECT id,code,name FROM sites WHERE status='active' AND deleted_at IS NULL ORDER BY name")->fetchAll(),'centers'=>$this->query("SELECT c.*,s.code site_code FROM cost_centers c JOIN sites s ON s.id=c.site_id WHERE c.status='active' AND c.deleted_at IS NULL ORDER BY s.code,c.name")->fetchAll(),'categories'=>$this->query("SELECT * FROM budget_categories WHERE status='active' AND deleted_at IS NULL ORDER BY code")->fetchAll(),'users'=>$this->query("SELECT id,name FROM users WHERE status='active' AND deleted_at IS NULL ORDER BY name")->fetchAll()];}
 public function createFiscalYear(array$d,array$u){if($d['end_date']<$d['start_date'])throw new RuntimeException('Dates exercice invalides.');$this->db->beginTransaction();try{$this->query("INSERT INTO budget_fiscal_years(code,start_date,end_date,status,created_by) VALUES(:code,:start,:end,'open',:user)",['code'=>trim($d['code']),'start'=>$d['start_date'],'end'=>$d['end_date'],'user'=>$u['id']]);$id=(int)$this->db->lastInsertId();$start=new DateTime($d['start_date']);for($i=1;$i<=12;$i++){$ps=(clone$start)->modify('+'.($i-1).' months');$pe=(clone$ps)->modify('last day of this month');$this->period($id,'monthly',$i,'Mois '.$i,$ps,$pe);}for($i=1;$i<=4;$i++){$ps=(clone$start)->modify('+'.(($i-1)*3).' months');$pe=(clone$ps)->modify('+3 months -1 day');$this->period($id,'quarterly',$i,'Trimestre '.$i,$ps,$pe);}$this->period($id,'annual',1,'Année '.$d['code'],new DateTime($d['start_date']),new DateTime($d['end_date']));$this->db->commit();return$id;}catch(Exception$e){$this->db->rollBack();throw$e;}}
 public function createBudget(array$d,array$u){$site=(int)$d['site_id'];Auth::requireSiteAccess($site);$center=$this->row('SELECT * FROM cost_centers WHERE id=? AND site_id=? AND deleted_at IS NULL',[$d['cost_center_id'],$site]);$amount=(float)$d['amount'];if(!$center||$amount<=0)throw new RuntimeException('Centre de coût ou montant invalide.');$n='BUD-'.date('YmdHis').'-'.random_int(100,999);$this->db->beginTransaction();try{$this->query("INSERT INTO budgets(fiscal_year_id,period_id,site_id,cost_center_id,budget_number,status,total_proposed,total_validated,created_by) VALUES(:year,:period,:site,:center,:number,'preparation',:amount,0,:user)",['year'=>$d['fiscal_year_id'],'period'=>$d['period_id'],'site'=>$site,'center'=>$center['id'],'number'=>$n,'amount'=>$amount,'user'=>$u['id']]);$id=(int)$this->db->lastInsertId();$this->query('INSERT INTO budget_lines(budget_id,category_id,proposed_amount,validated_amount,notes) VALUES(:budget,:category,:amount,0,:notes)',['budget'=>$id,'category'=>$d['category_id'],'amount'=>$amount,'notes'=>trim($d['notes']??'')?:null]);$this->history($id,null,'preparation','create',$u,null);$this->db->commit();return$id;}catch(Exception$e){$this->db->rollBack();throw$e;}}
 public function submit($id,array$u){$this->db->beginTransaction();try{$b=$this->lockBudget($id);if($b['status']!=='preparation')throw new RuntimeException('Budget non soumettable.');if((int)$b['created_by']!==(int)$u['id']&&!Auth::can('budgets','administer',$b['site_id']))throw new RuntimeException('Seul le préparateur peut soumettre.');$this->query("UPDATE budgets SET status='pending_df',submitted_at=NOW() WHERE id=:id",['id'=>$id]);$this->history($id,$b['status'],'pending_df','submit',$u,null);$this->db->commit();}catch(Exception$e){$this->db->rollBack();throw$e;}}
 public function approveDf($id,array$u){$this->db->beginTransaction();try{$b=$this->lockBudget($id);if($b['status']!=='pending_df')throw new RuntimeException('Budget non validable par la DF.');if((int)$b['created_by']===(int)$u['id'])throw new RuntimeException('Le créateur ne peut pas valider son budget.');$this->assertFinancialAuthority($u['id'],$b['site_id']);$settings=$this->settings($b['site_id']);$dg=(float)$b['total_proposed']>=(float)$settings['dg_budget_threshold'];$next=$dg?'pending_dg':'active';$this->query("UPDATE budget_lines SET validated_amount=proposed_amount WHERE budget_id=:id",['id'=>$id]);$this->query("UPDATE budgets SET status=:status,requires_dg=:dg,total_validated=total_proposed,df_validated_by=:user,df_validated_at=NOW(),activated_at=".($dg?'NULL':'NOW()')." WHERE id=:id",['status'=>$next,'dg'=>$dg?1:0,'user'=>$u['id'],'id'=>$id]);$this->history($id,$b['status'],$next,'validate_df',$u,null);$this->db->commit();}catch(Exception$e){$this->db->rollBack();throw$e;}}
 public function approveDg($id,array$u){$this->db->beginTransaction();try{$b=$this->lockBudget($id);if($b['status']!=='pending_dg')throw new RuntimeException('Budget non validable par la DG.');if((int)$b['created_by']===(int)$u['id'])throw new RuntimeException('Le créateur ne peut pas valider son budget.');$this->assertRole($u['id'],['directeur-general','direction','administrateur','administrateur-systeme'],$b['site_id']);$this->query("UPDATE budgets SET status='active',dg_validated_by=:user,dg_validated_at=NOW(),activated_at=NOW() WHERE id=:id",['user'=>$u['id'],'id'=>$id]);$this->history($id,$b['status'],'active','validate_dg',$u,null);$this->db->commit();}catch(Exception$e){$this->db->rollBack();throw$e;}}
 public function revise($id,array$d,array$u){$this->db->beginTransaction();try{$old=$this->lockBudget($id);if($old['status']!=='active')throw new RuntimeException('Seul un budget actif peut être révisé.');$amount=(float)$d['amount'];if($amount<=0)throw new RuntimeException('Montant révisé invalide.');$n=$old['budget_number'].'-R'.((int)$old['revision_number']+1);$this->query("INSERT INTO budgets(fiscal_year_id,period_id,site_id,cost_center_id,budget_number,revision_number,parent_budget_id,status,total_proposed,total_validated,created_by) VALUES(:year,:period,:site,:center,:number,:revision,:parent,'preparation',:amount,0,:user)",['year'=>$old['fiscal_year_id'],'period'=>$old['period_id'],'site'=>$old['site_id'],'center'=>$old['cost_center_id'],'number'=>$n,'revision'=>(int)$old['revision_number']+1,'parent'=>$old['id'],'amount'=>$amount,'user'=>$u['id']]);$new=(int)$this->db->lastInsertId();$line=$this->row('SELECT * FROM budget_lines WHERE budget_id=?',[$id]);$this->query('INSERT INTO budget_lines(budget_id,category_id,proposed_amount,validated_amount,notes) VALUES(:budget,:category,:amount,0,:notes)',['budget'=>$new,'category'=>$line['category_id'],'amount'=>$amount,'notes'=>'Révision: '.trim($d['reason'])]);$this->history($new,null,'preparation','revision',$u,trim($d['reason']));$this->db->commit();return$new;}catch(Exception$e){$this->db->rollBack();throw$e;}}
 public function createCommitment(array$d,array$u){$this->db->beginTransaction();try{$line=$this->lockLine($d['budget_line_id']);$amount=(float)$d['amount'];$available=$this->available($line['id']);if($amount<=0||$amount>$available)throw new RuntimeException('Budget disponible insuffisant pour cet engagement.');$n='ENG-'.date('YmdHis').'-'.random_int(100,999);$this->query("INSERT INTO budget_commitments(budget_line_id,commitment_number,description,amount,status,committed_at,created_by,approved_by) VALUES(:line,:number,:description,:amount,'approved',:at,:user,:approver)",['line'=>$line['id'],'number'=>$n,'description'=>trim($d['description']),'amount'=>$amount,'at'=>$d['committed_at'],'user'=>$u['id'],'approver'=>$u['id']]);$id=(int)$this->db->lastInsertId();$this->refreshAlerts($line['id']);$this->db->commit();return$id;}catch(Exception$e){$this->db->rollBack();throw$e;}}
 public function createExpense(array$d,array$u){$line=$this->lockLine($d['budget_line_id']);$amount=(float)$d['amount'];if($amount<=0)throw new RuntimeException('Montant de dépense invalide.');$commitment=null;if(!empty($d['commitment_id'])){$commitment=$this->row('SELECT * FROM budget_commitments WHERE id=? AND budget_line_id=? FOR UPDATE',[$d['commitment_id'],$line['id']]);if(!$commitment||$amount>((float)$commitment['amount']-(float)$commitment['realized_amount']))throw new RuntimeException('Engagement insuffisant.');}$available=$this->available($line['id']);$over=$amount>$available&&!$commitment;$settings=$this->settings($line['site_id']);$requiresDf=$amount>=(float)$settings['expense_df_threshold'];$status=$over?(trim($d['derogation_reason']??'')!==''?'derogation_pending':'blocked'):($requiresDf?'pending_df':'approved');$n='DEP-'.date('YmdHis').'-'.random_int(100,999);$this->db->beginTransaction();try{$this->query("INSERT INTO budget_expenses(budget_line_id,commitment_id,expense_number,site_id,cost_center_id,description,amount,expense_date,status,requires_df,created_by) VALUES(:line,:commitment,:number,:site,:center,:description,:amount,:date,:status,:df,:user)",['line'=>$line['id'],'commitment'=>$commitment['id']??null,'number'=>$n,'site'=>$line['site_id'],'center'=>$line['cost_center_id'],'description'=>trim($d['description']),'amount'=>$amount,'date'=>$d['expense_date'],'status'=>$status,'df'=>$requiresDf?1:0,'user'=>$u['id']]);$id=(int)$this->db->lastInsertId();if($status==='derogation_pending')$this->query("INSERT INTO budget_derogations(expense_id,reason,requested_by,status) VALUES(:expense,:reason,:user,'pending')",['expense'=>$id,'reason'=>trim($d['derogation_reason']),'user'=>$u['id']]);if($status==='approved')$this->realizeCommitment($commitment,$amount);$this->refreshAlerts($line['id']);$this->db->commit();return$id;}catch(Exception$e){$this->db->rollBack();throw$e;}}
 public function approveExpense($id,array$u){$this->db->beginTransaction();try{$e=$this->row('SELECT e.*,b.created_by budget_creator FROM budget_expenses e JOIN budget_lines l ON l.id=e.budget_line_id JOIN budgets b ON b.id=l.budget_id WHERE e.id=? FOR UPDATE',[$id]);if(!$e||$e['status']!=='pending_df')throw new RuntimeException('Dépense non validable par la DF.');if((int)$e['created_by']===(int)$u['id'])throw new RuntimeException('Le créateur ne peut pas valider sa dépense.');$this->assertFinancialAuthority($u['id'],$e['site_id']);$this->query("UPDATE budget_expenses SET status='approved',df_validated_by=:user,df_validated_at=NOW() WHERE id=:id",['user'=>$u['id'],'id'=>$id]);$c=$e['commitment_id']?$this->row('SELECT * FROM budget_commitments WHERE id=? FOR UPDATE',[$e['commitment_id']]):null;$this->realizeCommitment($c,$e['amount']);$this->refreshAlerts($e['budget_line_id']);$this->db->commit();}catch(Exception$e){$this->db->rollBack();throw$e;}}
 public function approveDerogation($id,array$u){$this->db->beginTransaction();try{$d=$this->row('SELECT d.*,e.site_id,e.budget_line_id,e.amount,e.created_by expense_creator FROM budget_derogations d JOIN budget_expenses e ON e.id=d.expense_id WHERE d.id=? FOR UPDATE',[$id]);if(!$d||$d['status']!=='pending')throw new RuntimeException('Dérogation non validable.');if((int)$d['requested_by']===(int)$u['id'])throw new RuntimeException('Le demandeur ne peut pas approuver sa dérogation.');$this->assertFinancialAuthority($u['id'],$d['site_id']);$this->query("UPDATE budget_derogations SET status='approved',approved_by=:user,approved_at=NOW() WHERE id=:id",['user'=>$u['id'],'id'=>$id]);$this->query("UPDATE budget_expenses SET status='approved',df_validated_by=:user,df_validated_at=NOW() WHERE id=:id",['user'=>$u['id'],'id'=>$d['expense_id']]);$this->refreshAlerts($d['budget_line_id']);$this->db->commit();}catch(Exception$e){$this->db->rollBack();throw$e;}}
 public function requestDelegation(array$d,array$u){$start=$d['starts_at'];$end=$d['expires_at'];if($end<=$start)throw new RuntimeException('Période de délégation invalide.');$this->assertRole($d['delegator_id'],['directeur-financier'],null);$this->query("INSERT INTO budget_df_delegations(delegator_id,delegate_id,site_id,starts_at,expires_at,status,reason,requested_by) VALUES(:delegator,:delegate,:site,:start,:end,'pending',:reason,:user)",['delegator'=>$d['delegator_id'],'delegate'=>$d['delegate_id'],'site'=>$d['site_id']?:null,'start'=>$start,'end'=>$end,'reason'=>trim($d['reason']),'user'=>$u['id']]);$id=(int)$this->db->lastInsertId();$this->delegationEvent($id,'requested',$u['id'],$d['reason']);return$id;}
 public function approveDelegation($id,array$u){$this->db->beginTransaction();try{$d=$this->row('SELECT * FROM budget_df_delegations WHERE id=? FOR UPDATE',[$id]);if(!$d||$d['status']!=='pending')throw new RuntimeException('Délégation non validable.');if((int)$d['requested_by']===(int)$u['id'])throw new RuntimeException('Le demandeur ne peut pas approuver la délégation.');$this->assertRole($u['id'],['directeur-general','direction','administrateur','administrateur-systeme'],null);$this->query("UPDATE budget_df_delegations SET status='approved',approved_by=:user,approved_at=NOW() WHERE id=:id",['user'=>$u['id'],'id'=>$id]);$this->delegationEvent($id,'approved',$u['id'],null);$this->db->commit();}catch(Exception$e){$this->db->rollBack();throw$e;}}
 public function report(){ $this->expireDelegations();$p=[];$scope=Auth::siteClause('b.site_id',$p);return$this->query("SELECT b.id,b.budget_number,b.revision_number,b.status,s.code site_code,c.code center_code,cat.code category_code,bl.validated_amount,COALESCE((SELECT SUM(amount-realized_amount) FROM budget_commitments WHERE budget_line_id=bl.id AND status IN('approved','partially_realized')),0) committed_open,COALESCE((SELECT SUM(amount) FROM budget_expenses WHERE budget_line_id=bl.id AND status='approved' AND deleted_at IS NULL),0) realized,bl.validated_amount-COALESCE((SELECT SUM(amount-realized_amount) FROM budget_commitments WHERE budget_line_id=bl.id AND status IN('approved','partially_realized')),0)-COALESCE((SELECT SUM(amount) FROM budget_expenses WHERE budget_line_id=bl.id AND status='approved' AND deleted_at IS NULL),0) available,DATEDIFF(p.end_date,p.start_date)+1 period_days,GREATEST(1,DATEDIFF(LEAST(CURDATE(),p.end_date),p.start_date)+1) elapsed_days FROM budgets b JOIN budget_lines bl ON bl.budget_id=b.id JOIN budget_categories cat ON cat.id=bl.category_id JOIN sites s ON s.id=b.site_id JOIN cost_centers c ON c.id=b.cost_center_id JOIN budget_periods p ON p.id=b.period_id WHERE b.status IN('active','replaced') AND b.deleted_at IS NULL{$scope} ORDER BY s.code,c.code,cat.code",$p)->fetchAll();}
 public function budgets(){ $p=[];$s=Auth::siteClause('b.site_id',$p);return$this->query("SELECT b.*,si.code site_code,c.code center_code,p.name period_name FROM budgets b JOIN sites si ON si.id=b.site_id JOIN cost_centers c ON c.id=b.cost_center_id JOIN budget_periods p ON p.id=b.period_id WHERE b.deleted_at IS NULL{$s} ORDER BY b.id DESC",$p)->fetchAll();}
 public function activeLines(){$p=[];$s=Auth::siteClause('b.site_id',$p);return$this->query("SELECT bl.id,b.budget_number,s.code site_code,c.code center_code,cat.code category_code,bl.validated_amount FROM budget_lines bl JOIN budgets b ON b.id=bl.budget_id JOIN sites s ON s.id=b.site_id JOIN cost_centers c ON c.id=b.cost_center_id JOIN budget_categories cat ON cat.id=bl.category_id WHERE b.status='active'{$s} ORDER BY s.code,c.code",$p)->fetchAll();}
 public function approvals(){return['expenses'=>$this->query("SELECT e.*,s.code site_code,c.code center_code FROM budget_expenses e JOIN sites s ON s.id=e.site_id JOIN cost_centers c ON c.id=e.cost_center_id WHERE e.status='pending_df' ORDER BY e.id DESC")->fetchAll(),'derogations'=>$this->query("SELECT d.*,e.expense_number,e.amount FROM budget_derogations d JOIN budget_expenses e ON e.id=d.expense_id WHERE d.status='pending' ORDER BY d.id DESC")->fetchAll(),'delegations'=>$this->query("SELECT d.*,u.name delegator_name,v.name delegate_name FROM budget_df_delegations d JOIN users u ON u.id=d.delegator_id JOIN users v ON v.id=d.delegate_id WHERE d.status='pending' ORDER BY d.id DESC")->fetchAll()];}
 private function available($line){$l=$this->row('SELECT validated_amount FROM budget_lines WHERE id=?',[$line]);$eng=(float)$this->query("SELECT COALESCE(SUM(amount-realized_amount),0) FROM budget_commitments WHERE budget_line_id=:id AND status IN('approved','partially_realized') AND deleted_at IS NULL",['id'=>$line])->fetchColumn();$spent=(float)$this->query("SELECT COALESCE(SUM(amount),0) FROM budget_expenses WHERE budget_line_id=:id AND status='approved' AND deleted_at IS NULL",['id'=>$line])->fetchColumn();return(float)$l['validated_amount']-$eng-$spent;}private function refreshAlerts($line){$l=$this->row('SELECT validated_amount FROM budget_lines WHERE id=?',[$line]);if(!$l||(float)$l['validated_amount']<=0)return;$used=(float)$l['validated_amount']-$this->available($line);$pct=$used/(float)$l['validated_amount']*100;foreach([80,100]as$t)if($pct>=$t)$this->query("INSERT INTO budget_alerts(budget_line_id,threshold_percent,consumption_percent,status) VALUES(:line,:threshold,:pct,'active') ON DUPLICATE KEY UPDATE consumption_percent=:pct2,status='active'",['line'=>$line,'threshold'=>$t,'pct'=>$pct,'pct2'=>$pct]);}private function realizeCommitment($c,$amount){if(!$c)return;$new=(float)$c['realized_amount']+(float)$amount;$status=$new>=(float)$c['amount']?'realized':'partially_realized';$this->query('UPDATE budget_commitments SET realized_amount=:amount,status=:status WHERE id=:id',['amount'=>$new,'status'=>$status,'id'=>$c['id']]);}
 private function lockBudget($id){$b=$this->row('SELECT * FROM budgets WHERE id=? AND deleted_at IS NULL FOR UPDATE',[$id]);if(!$b)throw new RuntimeException('Budget introuvable.');Auth::requireSiteAccess($b['site_id']);return$b;}private function lockLine($id){$l=$this->row("SELECT bl.*,b.site_id,b.cost_center_id,b.status FROM budget_lines bl JOIN budgets b ON b.id=bl.budget_id WHERE bl.id=? FOR UPDATE",[$id]);if(!$l||$l['status']!=='active')throw new RuntimeException('Ligne budgétaire inactive.');Auth::requireSiteAccess($l['site_id']);return$l;}private function settings($site){$s=$this->row('SELECT * FROM budget_settings WHERE site_id=?',[$site]);return$s?:$this->row('SELECT * FROM budget_settings WHERE site_id IS NULL ORDER BY id LIMIT 1');}
 private function assertFinancialAuthority($user,$site){if($this->hasRole($user,['directeur-financier','administrateur','administrateur-systeme'],$site))return;$this->expireDelegations();$ok=$this->query("SELECT COUNT(*) FROM budget_df_delegations WHERE delegate_id=:user AND status='approved' AND starts_at<=NOW() AND expires_at>NOW() AND (site_id IS NULL OR site_id=:site) AND deleted_at IS NULL",['user'=>$user,'site'=>$site])->fetchColumn();if(!$ok)throw new RuntimeException('Validation réservée au Directeur financier ou à son délégataire actif.');}private function assertRole($u,$roles,$site){if(!$this->hasRole($u,$roles,$site))throw new RuntimeException('Rôle requis absent.');}private function hasRole($u,$roles,$site){$in=implode(',',array_fill(0,count($roles),'?'));$params=array_merge([$u],$roles);$sql="SELECT COUNT(*) FROM user_role_assignments a JOIN roles r ON r.id=a.role_id WHERE a.user_id=? AND r.slug IN($in) AND a.approval_status='approved' AND a.starts_at<=NOW() AND (a.expires_at IS NULL OR a.expires_at>NOW()) AND a.deleted_at IS NULL";if($site!==null){$sql.=' AND (a.site_id IS NULL OR a.site_id=?)';$params[]=$site;}return(bool)$this->query($sql,$params)->fetchColumn();}
 private function expireDelegations(){$ids=$this->query("SELECT id FROM budget_df_delegations WHERE status='approved' AND expires_at<=NOW() FOR UPDATE")->fetchAll(PDO::FETCH_COLUMN);foreach($ids as$id){$this->query("UPDATE budget_df_delegations SET status='expired' WHERE id=:id",['id'=>$id]);$this->delegationEvent($id,'expired',null,'Expiration automatique');}}private function delegationEvent($id,$type,$actor,$details){$this->query('INSERT INTO budget_df_delegation_events(delegation_id,event_type,actor_id,details) VALUES(:id,:type,:actor,:details)',['id'=>$id,'type'=>$type,'actor'=>$actor,'details'=>$details]);}private function history($id,$old,$new,$action,$u,$reason){$this->query('INSERT INTO budget_history(budget_id,old_status,new_status,action,actor_id,reason) VALUES(:id,:old,:new,:action,:actor,:reason)',['id'=>$id,'old'=>$old,'new'=>$new,'action'=>$action,'actor'=>$u['id'],'reason'=>$reason]);}private function period($year,$type,$number,$name,DateTime$d1,DateTime$d2){$this->query('INSERT INTO budget_periods(fiscal_year_id,period_type,period_number,name,start_date,end_date) VALUES(:year,:type,:number,:name,:start,:end)',['year'=>$year,'type'=>$type,'number'=>$number,'name'=>$name,'start'=>$d1->format('Y-m-d'),'end'=>$d2->format('Y-m-d')]);}private function row($s,$p=[]){$q=$this->db->prepare($s);$q->execute($p);return$q->fetch();}
}
